:root {
  --bg: #0b1013;
  --ink: #eef5ea;
  --muted: #a9b8ae;
  --accent: #8ee06a;
  --accent-deep: #4f9d3a;
  --panel: rgba(12, 19, 22, 0.74);
  --panel-solid: #101a1e;
  --line: rgba(255, 255, 255, 0.12);
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.45);
  --radius: 18px;
  --ui: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  --mono: "SFMono-Regular", ui-monospace, "Cascadia Mono", Consolas, monospace;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--ui);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body {
  user-select: none;
  -webkit-user-select: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  touch-action: none;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  cursor: crosshair;
}

.hidden {
  display: none !important;
}

/* ---------- atmosphere ---------- */

#vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(120% 90% at 50% 45%, transparent 55%, rgba(4, 8, 10, 0.28) 100%),
    linear-gradient(to bottom, rgba(4, 8, 10, 0.18), transparent 18%, transparent 82%, rgba(4, 8, 10, 0.32));
  z-index: 2;
}

#underwater {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  background: linear-gradient(to bottom, rgba(20, 83, 133, 0.42), rgba(8, 38, 66, 0.62));
  box-shadow: inset 0 0 160px rgba(3, 20, 36, 0.8);
  transition: opacity 0.25s ease;
}

/* ---------- hud ---------- */

#hud {
  position: absolute;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  padding: calc(14px + env(safe-area-inset-top)) calc(16px + env(safe-area-inset-right))
    calc(14px + env(safe-area-inset-bottom)) calc(16px + env(safe-area-inset-left));
}

#stats {
  position: absolute;
  top: calc(14px + env(safe-area-inset-top));
  left: calc(16px + env(safe-area-inset-left));
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(7, 12, 14, 0.5);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: 0.02em;
  color: #d6e4d7;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.5);
}

#stats .dot {
  color: var(--accent);
}

#top-actions {
  position: absolute;
  top: calc(14px + env(safe-area-inset-top));
  right: calc(16px + env(safe-area-inset-right));
  display: flex;
  gap: 8px;
  pointer-events: auto;
}

.icon-btn {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 11px;
  border: 1px solid var(--line);
  background: rgba(7, 12, 14, 0.5);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: var(--ink);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.15s ease;
}

.icon-btn:hover {
  background: rgba(28, 44, 36, 0.75);
  transform: translateY(-1px);
}

.icon-btn svg {
  width: 20px;
  height: 20px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

#sound-btn .icon-off,
#sound-btn.muted .icon-on {
  display: none;
}

#sound-btn.muted .icon-off {
  display: block;
}

#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 22px;
  height: 22px;
  transform: translate(-50%, -50%);
  opacity: 0.9;
  filter: drop-shadow(0 0 1px rgba(0, 0, 0, 0.9));
}

#crosshair::before,
#crosshair::after {
  content: "";
  position: absolute;
  background: #fff;
  border-radius: 1px;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35);
}

#crosshair::before {
  left: 50%;
  top: 2px;
  width: 2px;
  height: 18px;
  transform: translateX(-50%);
}

#crosshair::after {
  top: 50%;
  left: 2px;
  height: 2px;
  width: 18px;
  transform: translateY(-50%);
}

#hotbar {
  position: absolute;
  left: 50%;
  bottom: calc(18px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  gap: 6px;
  padding: 7px;
  border-radius: 16px;
  border: 1px solid var(--line);
  background: rgba(7, 12, 14, 0.46);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  pointer-events: auto;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.25);
}

.slot {
  position: relative;
  width: 54px;
  height: 54px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.04);
  display: grid;
  place-items: center;
  cursor: pointer;
  padding: 0;
  transition: transform 0.13s ease, border-color 0.13s ease, background 0.13s ease;
}

.slot:hover {
  background: rgba(255, 255, 255, 0.09);
}

.slot.selected {
  border-color: rgba(142, 224, 106, 0.95);
  background: rgba(142, 224, 106, 0.14);
  transform: translateY(-5px);
  box-shadow: 0 0 0 1px rgba(142, 224, 106, 0.35), 0 8px 18px rgba(0, 0, 0, 0.25);
}

.slot canvas {
  width: 38px;
  height: 38px;
  image-rendering: pixelated;
  pointer-events: none;
}

.slot .num {
  position: absolute;
  left: 5px;
  top: 3px;
  font-family: var(--mono);
  font-size: 9px;
  color: rgba(255, 255, 255, 0.5);
}

#toast {
  position: absolute;
  left: 50%;
  bottom: calc(96px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  padding: 9px 15px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(8, 14, 16, 0.72);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  font-size: 12.5px;
  color: #e6f1e4;
  white-space: nowrap;
  opacity: 1;
  transition: opacity 0.4s ease, transform 0.4s ease;
  pointer-events: none;
}

#toast.fade {
  opacity: 0;
  transform: translate(-50%, 6px);
}

#hint {
  position: absolute;
  left: 50%;
  bottom: calc(88px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  font-size: 12px;
  color: rgba(230, 241, 228, 0.55);
  letter-spacing: 0.02em;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.8);
  white-space: nowrap;
  transition: opacity 0.6s ease;
}

/* ---------- overlays ---------- */

.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
}

.menu-overlay {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background:
    radial-gradient(90% 80% at 78% 32%, rgba(18, 44, 34, 0.18), transparent 60%),
    linear-gradient(90deg, rgba(5, 9, 11, 0.9) 0%, rgba(5, 9, 11, 0.66) 42%, rgba(5, 9, 11, 0.12) 100%),
    linear-gradient(to top, rgba(5, 9, 11, 0.82), transparent 42%);
}

.menu-shade {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(120% 120% at 50% 50%, transparent 40%, rgba(0, 0, 0, 0.4));
}

.menu-content {
  position: relative;
  z-index: 1;
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 48px;
  width: min(1180px, 100%);
  margin: 0 auto;
  padding: clamp(28px, 6vw, 72px) clamp(24px, 6vw, 76px);
}

.brand {
  max-width: 560px;
  animation: rise 0.7s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes rise {
  from {
    opacity: 0;
