input.newString:
findSpawn() {
  let best = null;
  for (let r = 0; r <= 76; r += 5) {
    const steps = r === 0 ? 1 : Math.max(8, Math.round(r * 0.75));
    for (let i = 0; i < steps; i++) {
      const angle = (i / steps) * Math.PI * 2 + r * 0.37;
      const gx = Math.round(Math.cos(angle) * r);
      const gz = Math.round(Math.sin(angle) * r);
      const h = this.heightAt(gx, gz);
      if (h < SEA_LEVEL + 2 || h > SEA_LEVEL + 14) continue;
      if (this.surfaceBlockAt(gx, gz, h) !== GRASS) continue;
      const biome = this.biomeAt(gx, gz, h);
      if (biome === 'forest' || biome === 'desert' || biome === 'snow') continue;

      let land = 0;
      let landSamples = 0;
      for (let dz = -12; dz <= 12; dz += 6) {
        for (let dx = -12; dx <= 12; dx += 6) {
          landSamples++;
          if (this.heightAt(gx + dx, gz + dz) > SEA_LEVEL) land++;
        }
      }

      let water = 0;
      let vista = 0;
      for (let d = 0; d < 8; d++) {
        const a = (d / 8) * Math.PI * 2;
        for (const dist of [16, 24, 32, 40]) {
          const hh = this.heightAt(gx + Math.round(Math.cos(a) * dist), gz + Math.round(Math.sin(a) * dist));
          if (hh < SEA_LEVEL) water += dist > 20 ? 1.6 : 0.8;
          vista = Math.max(vista, hh);
        }
      }

      let trees = 0;
      for (const [dx, dz] of [[0, 0], [3, 0], [-3, 0], [0, 3], [0, -3]]) {
        if (this.treeAt(gx + dx, gz + dz)) trees++;
      }

      const score =
        (land / landSamples) * 18 +
        water * 0.85 +
        vista * 0.16 -
        trees * 2.4 -
        Math.abs(h - (SEA_LEVEL + 7)) * 0.45 -
        r * 0.05;
      if (!best || score > best.score) best = { x: gx, z: gz, h, score };
    }
  }
  if (!best) {
    const h = this.heightAt(0, 0);
    best = { x: 0, z: 0, h: Math.max(h, SEA_LEVEL + 1), score: 0 };
  }
  return best;
}

scenicYaw(gx, gz) {
  let bestAngle = 0;
  let bestScore = -Infinity;
  for (let i = 0; i < 32; i++) {
    const a = (i / 32) * Math.PI * 2;
    let water = 0;
    let land = 0;
    let nearLand = 0;
    for (const dist of [10, 16, 24, 32, 40]) {
      const h = this.heightAt(gx + Math.round(Math.cos(a) * dist), gz + Math.round(Math.sin(a) * dist));
      if (h < SEA_LEVEL) {
        water += dist > 18 ? 1.6 : 0.7;
      } else {
        land += 1;
        if (dist <= 16) nearLand += 1;
      }
    }
    const score = water + land * 0.35 + nearLand * 0.5 - Math.max(0, water - 6) * 0.8;
    if (score > bestScore) {
      bestScore = score;
      bestAngle = a;
    }
  }
  const dx = Math.cos(bestAngle);
  const dz = Math.sin(bestAngle);
  return Math.atan2(-dx, -dz);
}

