function updateMenuCamera(dt) {
  menuTime += dt;
  const sway = Math.sin(menuTime * 0.16) * 3.2;
  const fx = -Math.sin(player.yaw);
  const fz = -Math.cos(player.yaw);
  const rx = Math.cos(player.yaw);
  const rz = -Math.sin(player.yaw);
  const desiredX = player.position.x - fx * 24 + rx * sway;
  const desiredZ = player.position.z - fz * 24 + rz * sway;
  let desiredY = player.position.y + 17 + Math.sin(menuTime * 0.22) * 0.6;
  const ground = Math.max(
    world.heightAt(Math.floor(desiredX), Math.floor(desiredZ)),
    world.heightAt(Math.floor((desiredX + player.position.x) / 2), Math.floor((desiredZ + player.position.z) / 2)),
  );
  desiredY = Math.max(desiredY, ground + 6.5);
  camera.position.set(desiredX, desiredY, desiredZ);
  tmpLook.set(player.position.x + fx * 18, player.position.y + 3, player.position.z + fz * 18);
  camera.lookAt(tmpLook);
  if (Math.abs(camera.fov - 64) > 0.01) {
    camera.fov = 64;
    camera.updateProjectionMatrix();
  }
}

