findSpawn() {
  let best = null;
  for (let r = 0; r <= 88; r += 5) {
    const steps = r === 0 ? 1 : Math.max(8, Math.round(r * 0.7));
    for (let i = 0; i < steps; i++) {
      const angle = (i / steps) * Math.PI * 2 + r * 0.37;
      const gx = Math.round(Math.cos(angle) * r);
      const gz = Math.round(Math.sin(angle) * r);
      const h = this.heightAt(gx, gz);
      if (h < SEA_LEVEL + 2 || h > SEA_LEVEL + 16) continue;
      if (this.surfaceBlockAt(gx, gz, h) !== GRASS) continue;
      const biome = this.biomeAt(gx, gz, h);
      if (biome === 'desert' || biome === 'snow') continue;

      let land = 0;
      let landSamples = 0;
      for (let dz = -16; dz <= 16; dz += 8) {
        for (let dx = -16; dx <= 16; dx += 8) {
          landSamples++;
          if (this.heightAt(gx + dx, gz + dz) > SEA_LEVEL) land++;
        }
      }
      if (land / landSamples < 0.5) continue;

      let minH = 999;
      let maxH = -999;
      for (let dz = -8; dz <= 8; dz += 4) {
        for (let dx = -8; dx <= 8; dx += 4) {
          const hh = this.heightAt(gx + dx, gz + dz);
          minH = Math.min(minH, hh);
          maxH = Math.max(maxH, hh);
        }
      }
      if (maxH - minH > 4) continue;

      // Pick the most open, scenic direction from this candidate.
      let view = null;
      for (let a = 0; a < 16; a++) {
        const ang = (a / 16) * Math.PI * 2;
        const dx = Math.cos(ang);
        const dz = Math.sin(ang);
        let open = 0;
        let water = 0;
        let sight = 0;
        let trees = 0;
        for (const dist of [4, 8, 12, 16, 24, 32, 40, 48]) {
          const hh = this.heightAt(gx + Math.round(dx * dist), gz + Math.round(dz * dist));
          if (hh <= h + 1) open++;
          if (hh < SEA_LEVEL) water += dist >= 20 ? 1.5 : 0.4;
          else sight += 0.35;
        }
        for (const dist of [8, 14]) {
          if (this.treeAt(gx + Math.round(dx * dist), gz + Math.round(dz * dist))) trees++;
        }
        const score = open * 1.15 + water + sight - trees * 2.6;
        if (!view || score > view.score) view = { angle: ang, score };
      }

      const candidateScore =
        view.score +
        (land / landSamples) * 12 -
        Math.abs(h - (SEA_LEVEL + 7)) * 0.3 -
        r * 0.035;
      if (!best || candidateScore > best.score) {
        best = {
          x: gx,
          z: gz,
          h,
          score: candidateScore,
          yaw: Math.atan2(-Math.cos(view.angle), -Math.sin(view.angle)),
        };
      }
    }
  }
  if (!best) {
    const h = this.heightAt(0, 0);
    best = {
      x: 0,
      z: 0,
      h: Math.max(h, SEA_LEVEL + 1),
      score: 0,
      yaw: this.scenicYaw(0, 0),
    };
  }
  return best;
}

