  for (let r = 0; r <= 76; r += 5) {
    const steps = r === 0 ? 1 : Math.max(8, Math.round(r * 0.75));
    for (let i = 0; i < steps; i++) {
      const angle = (i / steps) * Math.PI * 2 + r * 0.37;
      const gx = Math.round(Math.cos(angle) * r);
      const gz = Math.round(Math.sin(angle) * r);
      const h = this.heightAt(gx, gz);
      if (h < SEA_LEVEL + 2 || h > SEA_LEVEL + 14) continue;
      if (this.surfaceBlockAt(gx, gz, h) !== GRASS) continue;
      const biome = this.biomeAt(gx, gz, h);
      if (biome === 'forest' || biome === 'desert' || biome === 'snow') continue;

      let land = 0;
      let landSamples = 0;
      for (let dz = -16; dz <= 16; dz += 8) {
        for (let dx = -16; dx <= 16; dx += 8) {
          landSamples++;
          if (this.heightAt(gx + dx, gz + dz) > SEA_LEVEL) land++;
        }
      }
      if (land / landSamples < 0.55) continue;

      let slope = 0;
      for (let dz = -4; dz <= 4; dz += 2) {
        for (let dx = -4; dx <= 4; dx += 2) {
          slope = Math.max(slope, Math.abs(this.heightAt(gx + dx, gz + dz) - h));
        }
      }
      if (slope > 2) continue;

      let water = 0;
      let vista = 0;
      for (let d = 0; d < 8; d++) {
        const a = (d / 8) * Math.PI * 2;
        for (const dist of [24, 32, 40, 48]) {
          const hh = this.heightAt(gx + Math.round(Math.cos(a) * dist), gz + Math.round(Math.sin(a) * dist));
          if (hh < SEA_LEVEL) water += 1;
          vista = Math.max(vista, hh);
        }
      }

      let trees = 0;
      for (const [dx, dz] of [[0, 0], [3, 0], [-3, 0], [0, 3], [0, -3]]) {
        if (this.treeAt(gx + dx, gz + dz)) trees++;
      }

      const score =
        (land / landSamples) * 22 +
        water * 0.7 +
        vista * 0.15 -
        trees * 3 -
        Math.abs(h - (SEA_LEVEL + 6)) * 0.5 -
        r * 0.04;
      if (!best || score > best.score) best = { x: gx, z: gz, h, score };
    }
  }
  if (!best) {
    const h = this.heightAt(0, 0);
    best = { x: 0, z: 0, h: Math.max(h, SEA_LEVEL + 1), score: 0 };
  }
  return best;
}

