import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omniscient-playwright');
const reqPath = join(process.env.HOME, '.local/share/omgithub-playwright/package.json');
const require = createRequire(reqPath);
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(process.env.HOME, '.local/share/omgithub-playwright/display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto(process.env.URL || 'http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(2000);
const data = await page.evaluate(() => {
  const b = window.blockfall;
  const p = b.player;
  const x = Math.floor(p.position.x);
