import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.addInitScript(() => {
  localStorage.setItem(
    'blockfall.save.v1',
    JSON.stringify({ v: 1, seed: 123456789, edits: [], time: 0.34, player: null }),
  );
});
await page.goto(process.env.URL || 'http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1500);
const data = await page.evaluate(() => {
  const b = window.blockfall;
  const p = b.player;
  const x = Math.floor(p.position.x);
  const z = Math.floor(p.position.z);
  const fx = -Math.sin(p.yaw);
  const fz = -Math.cos(p.yaw);
  const corridor = [];
  for (let d = 1; d <= 40; d++) {
    const gx = x + Math.round(fx * d);
    const gz = z + Math.round(fz * d);
    corridor.push({ d, h: b.world.heightAt(gx, gz), tree: b.world.treeAt(gx, gz), biome: b.world.biomeAt(gx, gz) });
  }
  // coarse height map 49x49 centered on spawn, 4-block steps
  const map = [];
  for (let dz = -24; dz <= 24; dz += 4) {
    const row = [];
    for (let dx = -24; dx <= 24; dx += 4) {
      const h = b.world.heightAt(x + dx, z + dz);
      row.push(h);
    }
    map.push(row);
  }
  return {
    spawn: { x, z, y: p.position.y, yaw: p.yaw, yawDeg: (p.yaw * 180) / Math.PI },
    biome: b.world.biomeAt(x, z),
    corridor,
    map,
    time: b.environment.time,
  };
});
console.log(JSON.stringify(data, null, 2));
await browser.close();

