import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.addInitScript(() => {
  localStorage.setItem(
    'blockfall.save.v1',
    JSON.stringify({ v: 1, seed: 123456789, edits: [], time: 0.34, player: null }),
  );
});
await page.goto(process.env.URL || 'http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(2000);

// Enter playing then pause so the menu camera stops updating.
await page.click('#play-btn');
await page.waitForTimeout(800);
await page.keyboard.press('Escape');
await page.waitForTimeout(400);

const variants = [
  { name: 'a', back: 16, up: 28, ahead: 58, lookUp: 13, fov: 64 },
  { name: 'b', back: 24, up: 34, ahead: 64, lookUp: 10, fov: 66 },
  { name: 'c', back: 30, up: 44, ahead: 70, lookUp: 6, fov: 68 },
  { name: 'd', back: 12, up: 20, ahead: 60, lookUp: 18, fov: 62 },
];

for (const v of variants) {
  await page.evaluate((v) => {
    const b = window.blockfall;
    const p = b.player;
    const yaw = p.yaw;
    const fx = -Math.sin(yaw);
    const fz = -Math.cos(yaw);
    const rx = Math.cos(yaw);
    const rz = -Math.sin(yaw);
    const lookX = p.position.x + fx * v.ahead;
    const lookZ = p.position.z + fz * v.ahead;
    const ground = Math.max(b.world.heightAt(Math.floor(lookX), Math.floor(lookZ)), 24);
    const camX = p.position.x - fx * v.back + rx * 3;
    const camZ = p.position.z - fz * v.back + rz * 3;
    const camY = Math.max(p.position.y + v.up, b.world.heightAt(Math.floor(camX), Math.floor(camZ)) + 12, ground + 19);
    b.camera.position.set(camX, camY, camZ);
    b.camera.lookAt(lookX, ground + v.lookUp, lookZ);
    b.camera.fov = v.fov;
    b.camera.updateProjectionMatrix();
  }, v);
  await page.waitForTimeout(400);
  await page.screenshot({ path: `/home/runner/work/PlayGround/PlayGround/screenshots/menu-${v.name}.png` });
}
await browser.close();

