import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
mkdirSync('/home/runner/work/PlayGround/PlayGround/screenshots', { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => {
  if (m.type() === 'error') errors.push('ERROR: ' + m.text());
});
await page.addInitScript(() => {
  localStorage.setItem(
    'blockfall.save.v1',
    JSON.stringify({ v: 1, seed: 123456789, edits: [], time: 0.34, player: null }),
  );
});
await page.goto(process.env.URL || 'http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1800);
const log = {};

await page.click('#play-btn');
await page.waitForTimeout(900);
log.started = await page.evaluate(() => ({
  state: window.blockfall.state,
  locked: document.pointerLockElement === document.getElementById('game'),
  pos: window.blockfall.player.position.toArray(),
}));

// Walk forward.
const before = await page.evaluate(() => window.blockfall.player.position.toArray());
await page.keyboard.down('KeyW');
await page.waitForTimeout(700);
await page.keyboard.up('KeyW');
await page.waitForTimeout(200);
const after = await page.evaluate(() => window.blockfall.player.position.toArray());
log.walked = { before, after, dist: Math.hypot(after[0] - before[0], after[2] - before[2]) };

// Jump.
const y0 = await page.evaluate(() => window.blockfall.player.position.y);
await page.keyboard.down('Space');
await page.waitForTimeout(120);
await page.keyboard.up('Space');
await page.waitForTimeout(120);
const y1 = await page.evaluate(() => window.blockfall.player.position.y);
await page.waitForTimeout(900);
const y2 = await page.evaluate(() => window.blockfall.player.position.y);
log.jump = { y0, y1, y2, rose: y1 > y0 + 0.15, landed: Math.abs(y2 - y0) < 0.35 };

// Hotbar.
await page.keyboard.press('Digit3');
await page.waitForTimeout(150);
log.hotbar = await page.evaluate(() => ({
  selected: [...document.querySelectorAll('#hotbar .slot')].findIndex((s) => s.classList.contains('selected')),
  label: document.querySelector('#hotbar .slot.selected')?.getAttribute('aria-label'),
}));

// Aim at the ground a few blocks ahead and mine.
await page.evaluate(() => {
  const p = window.blockfall.player;
  p.pitch = -0.52;
});
await page.waitForTimeout(350);
const aimed = await page.evaluate(() => window.blockfall.target);
log.aimed = aimed;
if (aimed) {
  await page.evaluate(() => {
    const c = document.getElementById('game');
    c.dispatchEvent(new MouseEvent('mousedown', { button: 0, bubbles: true }));
  });
  await page.waitForTimeout(260);
  await page.evaluate(() => {
    const c = document.getElementById('game');
    window.dispatchEvent(new MouseEvent('mouseup', { button: 0, bubbles: true }));
  });
  await page.waitForTimeout(250);
  log.mined = await page.evaluate((t) => ({
    block: window.blockfall.world.getBlock(t.x, t.y, t.z),
    edits: window.blockfall.world.edits.size,
  }), aimed);
  await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/test-mined.png' });
}

// Place a block on the ground ahead.
await page.keyboard.press('Digit1');
await page.waitForTimeout(150);
await page.evaluate(() => {
  window.blockfall.player.pitch = -0.52;
});
await page.waitForTimeout(250);
const aimed2 = await page.evaluate(() => window.blockfall.target);
log.aimed2 = aimed2;
if (aimed2) {
  const expected = {
    x: aimed2.x + aimed2.normal[0],
    y: aimed2.y + aimed2.normal[1],
    z: aimed2.z + aimed2.normal[2],
  };
  await page.evaluate(() => {
    const c = document.getElementById('game');
    c.dispatchEvent(new MouseEvent('mousedown', { button: 2, bubbles: true }));
