import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.addInitScript(() => {
  if (!localStorage.getItem('blockfall.save.v1')) {
    localStorage.setItem(
      'blockfall.save.v1',
      JSON.stringify({ v: 1, seed: 123456789, edits: [], time: 0.34, player: null }),
    );
  }
});
await page.goto(process.env.URL || 'http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1800);
await page.click('#play-btn');
await page.waitForTimeout(900);

const out = [];
for (const pitch of [-0.3, -0.45, -0.6, -0.72, -0.85, -1.0]) {
  await page.evaluate((p) => {
    window.blockfall.player.pitch = p;
  }, pitch);
  await page.waitForTimeout(200);
  out.push(await page.evaluate((p) => {
    const b = window.blockfall;
    const t = b.target;
    const pos = b.player.position;
    if (!t) return { pitch: p, target: null, pos: pos.toArray() };
    return {
      pitch: p,
      target: t,
      pos: pos.toArray(),
      dist: Math.hypot(t.x + 0.5 - pos.x, t.z + 0.5 - pos.z),
      above: b.world.getBlock(t.x + t.normal[0], t.y + t.normal[1], t.z + t.normal[2]),
    };
  }, pitch));
}
console.log(JSON.stringify(out, null, 2));
await browser.close();

