input.content:
import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
mkdirSync('/home/runner/work/PlayGround/PlayGround/screenshots', { recursive: true });

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const context = await browser.newContext({
  viewport: { width: 390, height: 844 },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
});
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
page.on('console', (m) => {
  if (m.type() === 'error') errors.push('ERROR: ' + m.text());
});
await page.addInitScript(() => {
  if (!localStorage.getItem('blockfall.save.v1')) {
    localStorage.setItem(
      'blockfall.save.v1',
      JSON.stringify({ v: 1, seed: 123456789, edits: [], time: 0.34, player: null }),
    );
  }
});
await page.goto(process.env.URL || 'http://localhost:3002', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(2400);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-menu.png' });

const log = {};
log.menu = await page.evaluate(() => ({
  state: window.blockfall.state,
  title: document.querySelector('h1')?.getBoundingClientRect().toJSON(),
  play: document.getElementById('play-btn').getBoundingClientRect().toJSON(),
  newBtn: document.getElementById('new-btn').getBoundingClientRect().toJSON(),
  scrollWidth: document.documentElement.scrollWidth,
  innerWidth: window.innerWidth,
  innerHeight: window.innerHeight,
  touch: document.getElementById('touch-controls').className,
}));

await page.tap('#play-btn');
await page.waitForTimeout(1400);
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-game.png' });
log.playing = await page.evaluate(() => ({
  state: window.blockfall.state,
  touch: document.getElementById('touch-controls').className,
  hotbar: document.getElementById('hotbar').getBoundingClientRect().toJSON(),
  joystick: document.getElementById('joystick').getBoundingClientRect().toJSON(),
  mine: document.getElementById('mine-btn').getBoundingClientRect().toJSON(),
  place: document.getElementById('place-btn').getBoundingClientRect().toJSON(),
  jump: document.getElementById('jump-btn').getBoundingClientRect().toJSON(),
  toast: document.getElementById('toast').getBoundingClientRect().toJSON(),
  pos: window.blockfall.player.position.toArray(),
}));

const client = await context.newCDPSession(page);

// Joystick drag forward.
const joy = await page.evaluate(() => document.getElementById('joystick').getBoundingClientRect().toJSON());
const cx = joy.x + joy.width / 2;
const cy = joy.y + joy.height / 2;
const before = await page.evaluate(() => window.blockfall.player.position.toArray());
await client.send('Input.dispatchTouchEvent', {
  type: 'touchStart',
  touchPoints: [{ x: cx, y: cy, id: 1 }],
});
await client.send('Input.dispatchTouchEvent', {
  type: 'touchMove',
  touchPoints: [{ x: cx, y: cy - 30, id: 1 }],
});
await page.waitForTimeout(900);
await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await page.waitForTimeout(300);
const after = await page.evaluate(() => window.blockfall.player.position.toArray());
log.joystick = { before, after, dist: Math.hypot(after[0] - before[0], after[2] - before[2]) };

// Drag on the canvas to look.
const yaw0 = await page.evaluate(() => window.blockfall.player.yaw);
await client.send('Input.dispatchTouchEvent', {
  type: 'touchStart',
  touchPoints: [{ x: 195, y: 380, id: 2 }],
});
for (let i = 1; i <= 6; i++) {
  await client.send('Input.dispatchTouchEvent', {
    type: 'touchMove',
    touchPoints: [{ x: 195 + i * 12, y: 380, id: 2 }],
  });
  await page.waitForTimeout(30);
}
await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await page.waitForTimeout(300);
const yaw1 = await page.evaluate(() => window.blockfall.player.yaw);
log.look = { yaw0, yaw1, changed: Math.abs(yaw1 - yaw0) > 0.05 };

// Tap the canvas to mine a block under the crosshair.
await page.evaluate(() => {
  window.blockfall.player.pitch = -0.5;
});
await page.waitForTimeout(300);
const target = await page.evaluate(() => window.blockfall.target);
await page.touchscreen.tap(195, 380);
await page.waitForTimeout(400);
log.tapMine = {
  target,
  after: target ? await page.evaluate((t) => window.blockfall.world.getBlock(t.x, t.y, t.z), target) : null,
};

// Hold the mine button.
await page.evaluate(() => {
  window.blockfall.player.pitch = -0.5;
});
await page.waitForTimeout(250);
const target2 = await page.evaluate(() => window.blockfall.target);
const mineBtn = await page.evaluate(() => document.getElementById('mine-btn').getBoundingClientRect().toJSON());
await client.send('Input.dispatchTouchEvent', {
  type: 'touchStart',
  touchPoints: [{ x: mineBtn.x + mineBtn.width / 2, y: mineBtn.y + mineBtn.height / 2, id: 3 }],
});
await page.waitForTimeout(450);
await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await page.waitForTimeout(300);
log.holdMine = {
  target: target2,
  after: target2 ? await page.evaluate((t) => window.blockfall.world.getBlock(t.x, t.y, t.z), target2) : null,
  edits: await page.evaluate(() => window.blockfall.world.serializeEdits().length),
};

await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/mobile-after.png' });
log.errors = errors;
console.log(JSON.stringify(log, null, 2));
await browser.close();
